// SHERIVS-100 load setup: N synthetic schools (*.sim.invalid) with public content; 80% have a published site
// (doc from website-doc.json, generated by the engine), 20% are unpublished (renderer fallback path);
// every 10th school has a verified custom domain. Tokens in load/website-tokens.json (local HS256). Local sim only.
import pg from "pg"; import fs from "node:fs"; import crypto from "node:crypto";
const N = +(process.env.SCHOOLS || 1000), port = +(process.env.PGPORT || 54329);
const secret = fs.readFileSync("load/.jwt-secret", "utf8").trim();
const b64 = (o) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (p) => { const h = b64({ alg: "HS256", typ: "JWT" }) + "." + b64(p); return h + "." + crypto.createHmac("sha256", secret).update(h).digest("base64url"); };
const doc = fs.readFileSync(new URL("./website-doc.json", import.meta.url), "utf8");
const c = new pg.Client({ host: "127.0.0.1", port, user: "postgres" }); await c.connect();
const out = []; const run = crypto.randomUUID().slice(0, 6);
for (let i = 0; i < N; i++) {
  const sid = crypto.randomUUID(), admin = crypto.randomUUID(), slug = `web-${run}-${i}`;
  await c.query("INSERT INTO schools (id,name,slug,subscription_tier,subscription_status,is_active,max_students,phone,address,about) VALUES ($1,$2,$3,'growth','active',true,100000,'+234 800 000 0000','Lagos','About')", [sid, `Web Load ${i}`, slug]);
  await c.query("INSERT INTO auth.users (id,email) VALUES ($1,$2)", [admin, `wadmin-${admin.slice(0, 8)}@sim.invalid`]);
  await c.query("INSERT INTO users (id,school_id,full_name,email,role) VALUES ($1,$2,'Sim Admin',$3,'admin')", [admin, sid, `wadmin-${admin.slice(0, 8)}@sim.invalid`]);
  await c.query("INSERT INTO news (school_id,title,content,is_published,published_at) SELECT $1, $2 || ' news ' || g, 'body', true, now() - g * interval '1 day' FROM generate_series(1,8) g", [sid, slug]);
  await c.query("INSERT INTO events (school_id,title,event_date,is_published) SELECT $1, 'Event ' || g, current_date + g * 7, true FROM generate_series(1,4) g", [sid]);
  await c.query("INSERT INTO academic_programs (school_id,name,is_published,order_index) SELECT $1, 'Programme ' || g, true, g FROM generate_series(1,5) g", [sid]);
  await c.query("INSERT INTO faqs (school_id,question,answer,is_published,order_index) SELECT $1, 'Q' || g, 'A', true, g FROM generate_series(1,5) g", [sid]);
  await c.query("INSERT INTO school_staff (school_id,full_name,is_published,order_index) SELECT $1, $2 || ' staff ' || g, true, g FROM generate_series(1,20) g", [sid, slug]);
  await c.query("INSERT INTO school_sections (school_id,name,kind,residency) VALUES ($1,'Nursery','nursery','day'),($1,'Primary','primary','day')", [sid]);
  await c.query("INSERT INTO campuses (school_id,name,address) VALUES ($1,'Main','Lagos')", [sid]);
  let host = null;
  if (i % 10 === 0) { host = `www.web-${run}-${i}.sch.ng`; await c.query("INSERT INTO school_domains (school_id,hostname,purpose,status,is_primary) VALUES ($1,$2,'public_site','verified',true)", [sid, host]); }
  let rev = 0;
  if (i % 5 !== 4) {
    await c.query("BEGIN"); await c.query("select set_config('request.jwt.claims',$1,true)", [JSON.stringify({ sub: admin, role: "authenticated" })]);
    rev = (await c.query("select public.website_save_draft($1,$2::jsonb,0) r", [sid, doc])).rows[0].r;
    await c.query("select public.website_publish($1,'load seed')", [sid]); await c.query("COMMIT");
  }
  out.push({ t: sign({ sub: admin, role: "authenticated", exp: Math.floor(Date.now() / 1000) + 86400 }), school: sid, slug, host, published: rev > 0 });
}
fs.writeFileSync("load/website-tokens.json", JSON.stringify(out)); console.log(`schools: ${out.length}`); await c.end();
